import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthPage, ProfilePage, ManagerDashboardNew, ProtectedRoute } from "./components";
import PreciseBillParser from "./components/PreciseBillParser";
import OCRSpaceBillUpload from "./components/OCRSpaceBillUpload";
import EnhancedBillUpload from "./components/EnhancedBillUpload";
import "./styles.css";

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* Public Routes */}
          <Route path="/login" element={<AuthPage />} />
          <Route path="/register" element={<AuthPage />} />

          {/* Protected Routes */}
          <Route 
            path="/profile" 
            element={
              <ProtectedRoute>
                <ProfilePage />
              </ProtectedRoute>
            } 
          />
          {/* Removed non-working bill processing routes */}
          <Route 
            path="/team-bills" 
            element={
              <ProtectedRoute>
                <ManagerDashboardNew />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/precise-parser" 
            element={
              <ProtectedRoute>
                <PreciseBillParser />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/ocr-space-upload" 
            element={
              <ProtectedRoute>
                <OCRSpaceBillUpload />
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/enhanced-upload" 
            element={
              <ProtectedRoute>
                <EnhancedBillUpload />
              </ProtectedRoute>
            } 
          />

          {/* Default redirect */}
          <Route path="/" element={<Navigate to="/login" replace />} />
          <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
